def count_components_value(grid, target_val):
    """Count connected components of target value"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    comp_count = 0

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == target_val and (r,c) not in visited:
                # BFS to find component
                queue = [(r,c)]
                while queue:
                    cr, cc = queue.pop(0)
                    if (cr, cc) in visited:
                        continue
                    visited.add((cr, cc))
                    for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                        nr, nc = cr+dr, cc+dc
                        if 0 <= nr < rows and 0 <= nc < cols:
                            if grid[nr][nc] == target_val and (nr,nc) not in visited:
                                queue.append((nr, nc))
                comp_count += 1
    return comp_count

